import type { MP4Metadata, MP4Box } from './metadata';

export type MP4Buffer = Buffer | ArrayBuffer;

export interface MP4TagDefaultReadOptions {}

export interface MP4TagDefaultWriteOptions {}

export type MP4TagReadOptions = Partial<MP4TagDefaultReadOptions>;
export type MP4TagWriteOptions = Partial<MP4TagDefaultWriteOptions>;

export interface MP4DecodedMetadata {
  metadata: MP4Metadata;
  boxes: MP4Box[];
}

export class MP4Tag {
  readonly name = 'MP4Tag';
  readonly version = '0.1.0-beta';

  verbose: boolean;
  buffer: MP4Buffer;
  metadata: MP4Metadata;
  boxes: MP4Box[];
  error: string;

  static decodeMetadata (buffer: MP4Buffer, options?: MP4TagReadOptions, verbose?: boolean): MP4DecodedMetadata;
  static encodeMetadata (buffer: MP4Buffer, metadata: MP4Metadata, options?: MP4TagWriteOptions, verbose?: boolean): MP4Buffer;

  constructor (buffer: MP4Buffer, verbose?: boolean);
  read (options?: MP4TagReadOptions): MP4DecodedMetadata;
  save (options?: MP4TagWriteOptions): MP4Buffer;
}

export default MP4Tag;
